    .unwrap()
    .collect();
assert!(crls.len() >= 1);

// or one from a PEM byte slice...
# let byte_slice = include_bytes!("../tests/data/crl.pem");
CertificateRevocationListDer::from_pem_slice(byte_slice).unwrap();

